    <example> Create solid white fill layer: { preset: 'white' } </example>
    <example> Create 50% opacity white fill layer: { preset: 'white', opacity: 50 } </example>
    <example> Create custom RGB color fill layer: { color: { red: 255, green: 128, blue: 0 }, opacity: 75 } </example>
    <example> Create gray fill layer with multiply blend mode: { preset: 'gray', blendMode: 'multiply' } </example>

