$ErrorActionPreference = 'Stop'

$repoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$worktrees = @()
$entry = $null

foreach ($line in (& git -C $repoRoot worktree list --porcelain)) {
    if ($line.StartsWith('worktree ')) {
        if ($null -ne $entry) { $worktrees += $entry }
        $entry = [pscustomobject]@{ Path = $line.Substring(9); Branch = '' }
    } elseif ($line.StartsWith('branch ') -and $null -ne $entry) {
        $entry.Branch = $line.Substring(7)
    }
}
if ($null -ne $entry) { $worktrees += $entry }

$candidates = @($worktrees | Where-Object { $_.Path -ne $repoRoot })
if ($candidates.Count -eq 0) {
    Write-Host 'No other registered worktrees to clean up.'
    exit 0
}

Write-Host 'Registered worktrees (the current checkout is excluded):'
for ($i = 0; $i -lt $candidates.Count; $i++) {
    Write-Host "[$($i + 1)] $($candidates[$i].Path)  $($candidates[$i].Branch)"
}

$choice = Read-Host 'Enter the number of the settled thread worktree to remove (blank cancels)'
if ([string]::IsNullOrWhiteSpace($choice)) { Write-Host 'Cancelled.'; exit 0 }
if ($choice -notmatch '^\d+$' -or [int]$choice -lt 1 -or [int]$choice -gt $candidates.Count) {
    throw 'Choose one of the listed worktree numbers.'
}

$selected = $candidates[[int]$choice - 1]
$status = @(& git -C $selected.Path status --porcelain --untracked-files=all)
if ($LASTEXITCODE -ne 0) { throw 'Could not inspect the selected worktree.' }
if ($status.Count -gt 0) {
    Write-Host 'The selected worktree has uncommitted or untracked files. Nothing was removed.'
    exit 1
}

Write-Host "Selected: $($selected.Path)"
Write-Host 'This removes the checkout and its local files. Its branch and T3 thread history remain.'
$confirmation = Read-Host 'Type REMOVE only after the thread is settled and anything needed is committed or backed up'
if ($confirmation -cne 'REMOVE') { Write-Host 'Cancelled.'; exit 0 }

Set-Location $repoRoot
& git -C $repoRoot worktree remove -- $selected.Path
if ($LASTEXITCODE -ne 0) { throw 'Git could not remove the worktree; no force removal was attempted.' }
& git -C $repoRoot worktree prune
Write-Host 'Worktree removed; local branch and T3 thread history kept.'

